-- ISSUE-NOTES-E-2 (2026-11-05, charter pillar autonomy; cluster E-metrics-portfolio of the open-issue sweep; OWNER-NO-LOOSE-ENDS-1).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261105_e_issue_notes_2
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261105_e_issue_notes_2 b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261105_e_issue_notes_2)
-- CAUSE-MAPPED: no metric is registered here; this appends a dated finding to the description of two open issues (spofs_on_critical_path and the credential read-back audit).
-- Second round after migrations/2026-11-05-e-issue-notes.sql: two reads made after the first round merged. The notes carry no task, anchor or probe line, so no planner is handed a second copy of work another issue owns.

CREATE TABLE IF NOT EXISTS bak_20261105_e_issue_notes_2 AS SELECT id, description FROM agent_issues WHERE id IN (1000613, 1000982);

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05b (spofs_on_critical_path, GitHub 5284): read from spof_registry at 03:48Z, four registered single points of failure have no tested alternate (alternate_tested_at empty): the qnfo-evolve cron (alternate: POST /tick with the loop token), research publication structural validation (agent_issues 1000209; its own record says the alternate, the cloud-ops PUB-GATE-LOOP-1 quarantine, runs after publication and is not preventive), the qnfo-agents cron every 5 minutes (alternate: POST /requests/drain through the qnfo-ops AGENTS binding) and the kg curator (reviewed 2026-11-05T03:24:32Z by KG-CURATE-2; alternate: the repository_dispatch fleet-graph-tick that cloud-ops FLEET-GRAPH-CADENCE-1 sends). The count is not a regression of an existing path: a new registration joined the list after migrations/2026-11-05-e-spof-alternates-ran.sql recorded the two alternates that had run. Lever per row: a drill that exercises the alternate and writes spof_alternate_probes and alternate_tested_at (chaosDrill in qnfo-fleet-control). The evolve and agents alternates need the loop token, so that drill runs inside a worker that holds it, never from a session; the publication row needs a preventive second gate, not a drill. Closing probe: this issue contract (zero untested and the 7-day mean not rising).'
WHERE id = 1000613 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05b') = 0;

UPDATE agent_issues SET description = description || char(10) || char(10) || 'E-METRICS-PORTFOLIO 2026-11-05b (credential read-back, GitHub 6157): after PR 7525 (fleet-autoaudit.py stamps worker_live_audit.health_probed_at) the audit run of 03:38:37Z stamped 34 of the 131 rows; the contract probe, which counts live service_registry workers without a stamp under 3 hours old, then read one: qnfo-model-eval (registry state live, version 1.8.4-codeagent). That worker is folded into qnfo-ai-calibration (qnfo-model-eval/FOLDED, PR 7523) and the audit marks it RETIRED_PRESENT with the error text no /health read: the script still exists in the account and the audit does not read its /health. It clears when the fold deletes the script and the registry sets the row retired; the probe is not widened to skip such rows, because a credential that nothing reads back is exactly what this metric counts. Closing probe: this issue contract (0 live version credentials without a health-check read-back).'
WHERE id = 1000982 AND instr(description, 'E-METRICS-PORTFOLIO 2026-11-05b') = 0;
